<?php
if(!isset($db)){http_response_code(404);exit;}
function rewardSetup(){
q("CREATE TABLE IF NOT EXISTS onb_customer_codes(user_id INT PRIMARY KEY,code CHAR(32) NOT NULL UNIQUE) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_customer_offer(departure_id INT PRIMARY KEY,enabled TINYINT NOT NULL,credit DECIMAL(12,2) NOT NULL) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_customer_referrals(id INT AUTO_INCREMENT PRIMARY KEY,referrer INT NOT NULL,departure_id INT NOT NULL,referred INT NOT NULL UNIQUE,booking_id INT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'pending',credit DECIMAL(12,2) NOT NULL DEFAULT 0,ordinal INT NULL,UNIQUE(referrer,departure_id,ordinal)) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_customer_redemptions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,note VARCHAR(150) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
q("CREATE TABLE IF NOT EXISTS onb_customer_free(referrer INT NOT NULL,departure_id INT NOT NULL,redeemed_at DATETIME NULL,PRIMARY KEY(referrer,departure_id)) ENGINE=InnoDB");
}
function rewardBalance($id){return (float)q("SELECT COALESCE(SUM(credit),0) FROM onb_customer_referrals WHERE referrer=? AND status='verified'",[$id])->fetchColumn()-(float)q("SELECT COALESCE(SUM(amount),0) FROM onb_customer_redemptions WHERE user_id=?",[$id])->fetchColumn();}
function rewardAction($action,$u,$admin){global $db;if(!$u)throw new RuntimeException('Sign in required.');rewardSetup();departureSetup();bookingSetup();agentSetup();
if($action==='reward_offer'&&$admin){$id=(int)p('departure');if(!q('SELECT id FROM onb_departures WHERE id=?',[$id])->fetchColumn())throw new RuntimeException('Invalid departure.');$amount=depNumber('credit',1000);q('INSERT INTO onb_customer_offer VALUES(?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),credit=VALUES(credit)',[$id,p('enabled')==='1'?1:0,$amount]);go('page=rewards');}
if($action==='reward_claim'&&!$admin){$code=p('code');$id=(int)p('departure');$owner=q('SELECT user_id FROM onb_customer_codes WHERE code=?',[$code])->fetchColumn();if(!$owner||(int)$owner===(int)$u['id']||agentActive($owner)||agentActive($u['id'])||isset($_SESSION['agent_ref']))throw new RuntimeException('Referral not eligible.');if(!q('SELECT d.id FROM onb_departures d JOIN onb_customer_offer o ON o.departure_id=d.id JOIN trips t ON t.id=d.trip_id WHERE d.id=? AND d.active=1 AND o.enabled=1 AND t.published=1 AND d.start_date>=CURRENT_DATE',[$id])->fetchColumn())throw new RuntimeException('Offer unavailable.');q('INSERT INTO onb_customer_referrals(referrer,departure_id,referred) VALUES(?,?,?)',[$owner,$id,$u['id']]);go('page=rewards');}
if($action==='reward_verify'&&$admin){$db->beginTransaction();try{$r=q('SELECT * FROM onb_customer_referrals WHERE id=? FOR UPDATE',[(int)p('id')])->fetch();if(!$r||$r['status']!=='pending')throw new RuntimeException('Referral already reviewed.');q('SELECT id FROM users WHERE id=? FOR UPDATE',[$r['referrer']]);$o=q('SELECT * FROM onb_customer_offer WHERE departure_id=? FOR UPDATE',[$r['departure_id']])->fetch();$d=q('SELECT * FROM onb_departures WHERE id=?',[$r['departure_id']])->fetch();$b=q('SELECT * FROM onb_bookings WHERE id=? FOR UPDATE',[(int)p('booking')])->fetch();if(!$o||!$o['enabled']||!$d||!$b||$b['agent_id']||agentActive($r['referrer'])||agentActive($r['referred'])||(int)$b['user_id']!==(int)$r['referred']||(int)$b['trip_id']!==(int)$d['trip_id']||!in_array($b['stage'],['confirmed','completed'],true)||bookingNet($b['id'])<(float)$b['price']||!q("SELECT id FROM onb_departure_requests WHERE departure_id=? AND user_id=? AND status='reserved' AND adults+children=1",[$d['id'],$r['referred']])->fetchColumn())throw new RuntimeException('Requires a fully paid direct booking and matching single-traveller reserved departure.');$n=1+(int)q("SELECT COUNT(*) FROM onb_customer_referrals WHERE referrer=? AND departure_id=? AND status='verified'",[$r['referrer'],$d['id']])->fetchColumn();if($n>10)throw new RuntimeException('Ten-referral offer already earned.');q("UPDATE onb_customer_referrals SET booking_id=?,status='verified',ordinal=?,credit=? WHERE id=?",[$b['id'],$n,$n===10?0:$o['credit'],$r['id']]);if($n===10)q('INSERT INTO onb_customer_free(referrer,departure_id) VALUES(?,?)',[$r['referrer'],$d['id']]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=rewards');}
if($action==='reward_redeem'&&$admin){$id=(int)p('user');$amount=bookingAmount('amount');$db->beginTransaction();try{if(!q('SELECT id FROM users WHERE id=? FOR UPDATE',[$id])->fetchColumn()||!p('note')||(float)$amount>rewardBalance($id))throw new RuntimeException('Insufficient credit or missing reference.');q('INSERT INTO onb_customer_redemptions(user_id,amount,note) VALUES(?,?,?)',[$id,$amount,p('note')]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=rewards');}
if($action==='reward_free'&&$admin){q('UPDATE onb_customer_free SET redeemed_at=NOW() WHERE referrer=? AND departure_id=? AND redeemed_at IS NULL',[(int)p('user'),(int)p('departure')]);go('page=rewards');}
throw new RuntimeException('Access denied.');}
function rewardView($u,$admin){global $c;if($admin)premiumHero('Customer Referral Management','Manage departure offers, verified referrals, credits and free trip rewards in CAD.');else premiumHero('Bring 10. Travel Free.','Earn CAD 50 for each of your first nine eligible referrals on a participating departure. Your tenth unlocks a free standard trip instead of another credit.');if(!$u){premiumLink('?page=login','Sign in to participate');return;}rewardSetup();departureSetup();bookingSetup();
if($admin){rewardAdmin();return;}
if(agentActive($u['id'])){echo '<p>Professional agents use the separate agent programme.</p>';return;}q('INSERT IGNORE INTO onb_customer_codes VALUES(?,?)',[$u['id'],bin2hex(random_bytes(16))]);$code=q('SELECT code FROM onb_customer_codes WHERE user_id=?',[$u['id']])->fetchColumn();echo '<div class="metrics"><article>Travel credit balance<strong>CAD '.number_format(rewardBalance($u['id']),2).'</strong></article></div><p>Your referral link: '.h(($c['public_url']??'').'?page=rewards&invite='.$code).'</p><p>Share your link. Credits are not cash and require manual approval. Optional extras are excluded from the free trip.</p>';foreach(q('SELECT d.id,d.start_date,t.title,o.credit FROM onb_departures d JOIN onb_customer_offer o ON o.departure_id=d.id JOIN trips t ON t.id=d.trip_id WHERE o.enabled=1 AND d.active=1 AND t.published=1 AND d.start_date>=CURRENT_DATE') as $d){$n=(int)q("SELECT COUNT(*) FROM onb_customer_referrals WHERE referrer=? AND departure_id=? AND status='verified'",[$u['id'],$d['id']])->fetchColumn();echo '<article><h2>'.h($d['title'].' · '.$d['start_date']).'</h2><progress max="10" value="'.$n.'"></progress><p>'.$n.' / 10 verified · CAD '.h($d['credit']).' per first nine</p>';if($n===10)echo '<strong>Free trip unlocked — contact our team to arrange your seat.</strong>';form('reward_claim');echo '<input type="hidden" name="departure" value="'.h($d['id']).'">';field('code','Referral code from your friend',$_GET['invite']??'');echo '<button>Register referral</button></form></article>';}}

function rewardAdmin(){
$offers=q('SELECT d.id,d.start_date,t.title,o.enabled,o.credit FROM onb_departures d JOIN trips t ON t.id=d.trip_id LEFT JOIN onb_customer_offer o ON o.departure_id=d.id ORDER BY d.start_date')->fetchAll();
$refs=q("SELECT r.*,u.email AS referred_email,v.email AS referrer_email,t.title,d.start_date,b.ref AS booking_ref FROM onb_customer_referrals r JOIN users u ON u.id=r.referred JOIN users v ON v.id=r.referrer JOIN onb_departures d ON d.id=r.departure_id JOIN trips t ON t.id=d.trip_id LEFT JOIN onb_bookings b ON b.id=r.booking_id ORDER BY r.id DESC")->fetchAll();
$history=q('SELECT x.*,u.email FROM onb_customer_redemptions x JOIN users u ON u.id=x.user_id ORDER BY x.id DESC')->fetchAll();
$free=q('SELECT f.*,u.email,t.title,d.start_date FROM onb_customer_free f JOIN users u ON u.id=f.referrer JOIN onb_departures d ON d.id=f.departure_id JOIN trips t ON t.id=d.trip_id ORDER BY d.start_date DESC')->fetchAll();
$pending=0;$verified=0;$issued=0;$spent=0;foreach($refs as $r){if($r['status']==='pending')$pending++;if($r['status']==='verified'){$verified++;$issued+=(float)$r['credit'];}}foreach($history as $x)$spent+=(float)$x['amount'];
echo '<div class="onb-dash"><div class="metrics">';foreach(['Total referrals'=>count($refs),'Pending verification'=>$pending,'Verified referrals'=>$verified,'Credits issued (CAD)'=>number_format($issued,2),'Outstanding credits (CAD)'=>number_format($issued-$spent,2),'Free trips earned'=>count($free)] as $label=>$value)echo '<article><span>'.h($label).'</span><strong>'.h($value).'</strong></article>';echo '</div><p><a href="#reward-offers">Configure referral offers</a> · <a href="#reward-register">Referral management</a> · <a href="#reward-history">Redemption history</a> · <a href="#reward-free">Free trips</a></p>';
echo '<article id="reward-offers"><h2>Configure referral offers</h2><p>Set the credit for the first nine referrals. The tenth unlocks a free trip on the same departure.</p>';if(!$offers)echo '<p>No departures created yet. Create a dated departure before enabling an offer.</p><a href="?page=departures">Manage departures</a>';foreach($offers as $d){form('reward_offer');echo '<strong>'.h($d['title'].' · '.$d['start_date']).'</strong><input type="hidden" name="departure" value="'.h($d['id']).'"><label>Offer<select name="enabled"><option value="0">Disabled</option><option value="1" '.($d['enabled']?'selected':'').'>Enabled</option></select></label>';field('credit','CAD per first nine referrals',$d['credit']??'50');echo '<button>Save offer</button></form>';}echo '</article>';
echo '<article id="reward-register"><h2>Referral management</h2><div class="dash-table"><table><thead><tr><th>Referrer</th><th>Referred traveller</th><th>Departure</th><th>Status</th><th>Credit CAD</th><th>Booking / action</th></tr></thead><tbody>';if(!$refs)echo '<tr><td colspan="6">No referrals yet. Registered customer referrals will appear here.</td></tr>';foreach($refs as $r){echo '<tr><td>'.h($r['referrer_email']).'</td><td>'.h($r['referred_email']).'</td><td>'.h($r['title'].' · '.$r['start_date']).'</td><td>'.h($r['status']).'</td><td>'.h($r['credit']).'</td><td>'.h($r['booking_ref']??'');if($r['status']==='pending'){form('reward_verify');echo '<input type="hidden" name="id" value="'.h($r['id']).'"><label>Matching booking<select name="booking" required><option value="">Select booking</option>';foreach(q('SELECT id,ref FROM onb_bookings WHERE user_id=?',[$r['referred']]) as $b)echo '<option value="'.h($b['id']).'">'.h($b['ref']).'</option>';echo '</select></label><button>Verify paid referral</button></form>';}echo '</td></tr>';}echo '</tbody></table></div></article>';
echo '<article><h2>Customer credit balances</h2>'; $customers=q('SELECT DISTINCT r.referrer,u.email FROM onb_customer_referrals r JOIN users u ON u.id=r.referrer')->fetchAll();if(!$customers)echo '<p>No customer credit accounts yet.</p>';foreach($customers as $r){form('reward_redeem');echo '<p>'.h($r['email']).' · CAD '.number_format(rewardBalance($r['referrer']),2).'</p><input type="hidden" name="user" value="'.h($r['referrer']).'">';field('amount','Credit applied CAD');field('note','Booking reference');echo '<button>Record manual redemption</button></form>';}echo '</article>';
echo '<article id="reward-history"><h2>Reward redemption history</h2><div class="dash-table"><table><thead><tr><th>Date</th><th>Customer</th><th>CAD redeemed</th><th>Reference</th></tr></thead><tbody>';if(!$history)echo '<tr><td colspan="4">No credits redeemed yet.</td></tr>';foreach($history as $x)echo '<tr><td>'.h($x['created_at']).'</td><td>'.h($x['email']).'</td><td>'.h($x['amount']).'</td><td>'.h($x['note']).'</td></tr>';echo '</tbody></table></div></article>';
echo '<article id="reward-free"><h2>Free trip rewards</h2><div class="dash-table"><table><thead><tr><th>Customer</th><th>Departure</th><th>Status</th><th>Action</th></tr></thead><tbody>';if(!$free)echo '<tr><td colspan="4">No free trips earned yet.</td></tr>';foreach($free as $f){echo '<tr><td>'.h($f['email']).'</td><td>'.h($f['title'].' · '.$f['start_date']).'</td><td>'.h($f['redeemed_at']??'Awaiting fulfilment').'</td><td>';if(!$f['redeemed_at']){form('reward_free');echo '<input type="hidden" name="user" value="'.h($f['referrer']).'"><input type="hidden" name="departure" value="'.h($f['departure_id']).'"><button>Mark fulfilled</button></form>';}echo '</td></tr>';}echo '</tbody></table></div></article></div>';
}
